#!/usr/bin/env bash
set -Eeuo pipefail

cd "$HOME/Downloads"

DEV="${TSP_DEV:-root@192.168.1.25}"
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
ROOT="/mnt/SDCARD/data/ports/openmw51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
BASE="$MOD/scripts/TSPInteriorVisGrid"
LIVE_LUA="$BASE/visgrid.lua"
PROFILE_DIR="$BASE/v23_profiles"
TOPOLOGY="$BASE/topology.lua"
TOPOLOGY_CELLS="$BASE/topology_cells"
DOORGRAPH="$BASE/doorgraph.lua"
DOORGRAPH_CELLS="$BASE/doorgraph_cells"
DB="/mnt/UDISK/openmw51-nav/navmesh.db"
GAME="$ROOT/bin/openmw-0.51"

EXPECTED_BASE_SHA="cd422b72de855afd1853267e321ee86da426bee7c6c78293cee958f1c7645ebb"
EXPECTED_DIAG_SHA="5cf1008e819d98ab34bcf73f8562b08dd9fcb9459e276d3f216e1f65b3cc1963"
EXPECTED_T0P0_SHA="7958afb193929e40890c6aec74482a6cfba6b518056ca21349a2cf06c6020445"
EXPECTED_T0P1_SHA="8d13babd7950a57c8957070f0ac89c00a3ceadb8fbaddcda606f4191c4112076"
EXPECTED_T1P0_SHA="76e1cd1b3eeb7b8f50fd2473d8348ef55ef43712c414c0158923cfa69193bc32"
EXPECTED_T1P1_SHA="ed155ccd7bea88becce3d9f6a262a77b9c20fe91859d020a14bd41fcb3797c5e"
EXPECTED_GAME_SHA="5ba39a9869c592f1e21349521ad19fce0a04c6d03bb378c22170929c9792c555"
EXPECTED_TOPO_SHA="528802bf4e8913dc3629c5c46f204b01ab0087de533331ca3ef6d5f86bbfafc4"
EXPECTED_DOOR_SHA="a3afb045f9937e312580ae7def86456e0401a888608f8f088c9f3ac785e84dac"
EXPECTED_DB_STAT="934629376 1787961889"
EXPECTED_TOPO_COUNT="1321"
EXPECTED_DOOR_COUNT="1317"

STAMP="$(date +%Y%m%d-%H%M%S)"
PKG="$HOME/Downloads/openmw51-visgrid-v23-perf-matrix-$STAMP"
LOG="$HOME/Downloads/install-visgrid-v23-perf-matrix-$STAMP.txt"
BACKUP="$MOD/v23-backups/$STAMP"
BACKUP_READY=0
LAUNCHER=""

mkdir -p "$PKG"
exec > >(tee "$LOG") 2>&1

fail() { echo "ERROR: $*" >&2; exit 1; }
sha64() { [[ "$1" =~ ^[0-9a-f]{64}$ ]]; }
assert_eq() {
    local what="$1" got="$2" want="$3"
    [ "$got" = "$want" ] || fail "$what mismatch: got '$got' expected '$want'"
}
remote_sha() { ssh "${SSH[@]}" "$DEV" "sha256sum '$1'" | awk 'NF {print $1; exit}' | tr -d '\r'; }

rollback_on_error() {
    local rc=$?
    trap - ERR
    set +e
    if [ "$BACKUP_READY" = 1 ] && [ -n "$LAUNCHER" ]; then
        echo
        echo "===== ERROR: RESTORING PRE-V23 SENSOR + LAUNCHER ====="
        ssh "${SSH[@]}" "$DEV" "
            set -e
            test -s '$BACKUP/visgrid.lua.before'
            test -s '$BACKUP/launcher.before'
            cp -p '$BACKUP/visgrid.lua.before' '$LIVE_LUA.rollback-new'
            mv -f '$LIVE_LUA.rollback-new' '$LIVE_LUA'
            cp -p '$BACKUP/launcher.before' '$LAUNCHER.rollback-new'
            chmod +x '$LAUNCHER.rollback-new'
            mv -f '$LAUNCHER.rollback-new' '$LAUNCHER'
            sync
        "
        echo "Rollback attempted from: $BACKUP"
    fi
    echo "Installer log: $LOG"
    exit "$rc"
}
trap rollback_on_error ERR

for h in "$EXPECTED_BASE_SHA" "$EXPECTED_DIAG_SHA" "$EXPECTED_T0P0_SHA" "$EXPECTED_T0P1_SHA" "$EXPECTED_T1P0_SHA" "$EXPECTED_T1P1_SHA" "$EXPECTED_GAME_SHA" "$EXPECTED_TOPO_SHA" "$EXPECTED_DOOR_SHA"; do
    sha64 "$h" || fail "internal SHA constant is malformed: $h"
done
for c in ssh scp sha256sum python3 base64 awk grep sed bash; do command -v "$c" >/dev/null || fail "missing host command: $c"; done

echo "=================================================================="
echo "OPENMW 0.51 TSP — VISGRID V23 PERFORMANCE MATRIX"
echo "=================================================================="
echo "This is a Lua + launcher-only experiment."
echo "It does NOT rebuild OpenMW, regenerate topology, touch doorgraph data,"
echo "or copy/modify the canonical navmesh.db."
echo "No OpenMW process-name gate is used."
echo

echo "===== 1/9 VERIFY PROTECTED DEVICE STATE ====="
ssh "${SSH[@]}" "$DEV" "
    set -e
    test -s '$GAME'
    test -s '$LIVE_LUA'
    test -s '$TOPOLOGY'
    test -s '$DOORGRAPH'
    test -d '$TOPOLOGY_CELLS'
    test -d '$DOORGRAPH_CELLS'
    test -s '$DB'
"

LAUNCHER="$(ssh "${SSH[@]}" "$DEV" '
    ROOT=/mnt/SDCARD/data/ports/openmw51
    for p in \
      /mnt/SDCARD/Roms/PORTS/Morrowind_51.sh \
      /mnt/SDCARD/Emus/PORTS/../../Roms/PORTS/Morrowind_51.sh \
      /mnt/SDCARD/roms/ports/Morrowind_51.sh \
      "$ROOT/Morrowind_51.sh"
    do
      if [ -f "$p" ]; then
        readlink -f "$p" 2>/dev/null || printf "%s\n" "$p"
        exit 0
      fi
    done
    exit 1
' | head -1 | tr -d '\r')"
[ -n "$LAUNCHER" ] || fail "could not locate live Morrowind_51.sh"

echo "Launcher: $LAUNCHER"

GAME_SHA_BEFORE="$(remote_sha "$GAME")"
TOPO_SHA_BEFORE="$(remote_sha "$TOPOLOGY")"
DOOR_SHA_BEFORE="$(remote_sha "$DOORGRAPH")"
DB_STAT_BEFORE="$(ssh "${SSH[@]}" "$DEV" "stat -c '%s %Y' '$DB'" | awk 'NF>=2 {print $1, $2; exit}' | tr -d '\r')"
TOPO_COUNT_BEFORE="$(ssh "${SSH[@]}" "$DEV" "find '$TOPOLOGY_CELLS' -maxdepth 1 -type f -name 'c_*.lua' | wc -l" | awk 'NF {print $1; exit}' | tr -d '\r')"
DOOR_COUNT_BEFORE="$(ssh "${SSH[@]}" "$DEV" "find '$DOORGRAPH_CELLS' -maxdepth 1 -type f -name 'c_*.lua' | wc -l" | awk 'NF {print $1; exit}' | tr -d '\r')"
LIVE_SHA_BEFORE="$(remote_sha "$LIVE_LUA")"
LAUNCHER_SHA_BEFORE="$(remote_sha "$LAUNCHER")"

echo "game SHA:        $GAME_SHA_BEFORE"
echo "sensor SHA:      $LIVE_SHA_BEFORE"
echo "topology SHA:    $TOPO_SHA_BEFORE"
echo "doorgraph SHA:   $DOOR_SHA_BEFORE"
echo "DB size/mtime:   $DB_STAT_BEFORE"
echo "topology shards: $TOPO_COUNT_BEFORE"
echo "doorgraph shards: $DOOR_COUNT_BEFORE"
echo "launcher SHA:    $LAUNCHER_SHA_BEFORE"

assert_eq "protected game SHA" "$GAME_SHA_BEFORE" "$EXPECTED_GAME_SHA"
assert_eq "protected topology SHA" "$TOPO_SHA_BEFORE" "$EXPECTED_TOPO_SHA"
assert_eq "protected doorgraph SHA" "$DOOR_SHA_BEFORE" "$EXPECTED_DOOR_SHA"
assert_eq "canonical DB size/mtime" "$DB_STAT_BEFORE" "$EXPECTED_DB_STAT"
assert_eq "topology shard count" "$TOPO_COUNT_BEFORE" "$EXPECTED_TOPO_COUNT"
assert_eq "doorgraph shard count" "$DOOR_COUNT_BEFORE" "$EXPECTED_DOOR_COUNT"

echo
echo "===== 2/9 ACQUIRE EXACT V22.1G BASELINE + LIVE LAUNCHER ====="
BASE_LOCAL="$PKG/visgrid-v22.1g-baseline.lua"
LAUNCHER_LOCAL="$PKG/Morrowind_51.before-v23.sh"

if [ "$LIVE_SHA_BEFORE" = "$EXPECTED_BASE_SHA" ]; then
    echo "Using exact live V22.1G as generation base."
    scp -q "${SSH[@]}" "$DEV:$LIVE_LUA" "$BASE_LOCAL"
else
    STAGED_BASE_SHA="$(ssh "${SSH[@]}" "$DEV" "if [ -s '$PROFILE_DIR/visgrid-v22.1g-baseline.lua' ]; then sha256sum '$PROFILE_DIR/visgrid-v22.1g-baseline.lua'; fi" | awk 'NF {print $1; exit}' | tr -d '\r')"
    if [ "$STAGED_BASE_SHA" = "$EXPECTED_BASE_SHA" ]; then
        echo "Live sensor is already another profile; using staged exact V22.1G baseline."
        scp -q "${SSH[@]}" "$DEV:$PROFILE_DIR/visgrid-v22.1g-baseline.lua" "$BASE_LOCAL"
    else
        fail "neither live sensor nor staged baseline is exact V22.1G; refusing to patch an unknown sensor"
    fi
fi
scp -q "${SSH[@]}" "$DEV:$LAUNCHER" "$LAUNCHER_LOCAL"
assert_eq "fetched V22.1G baseline SHA" "$(sha256sum "$BASE_LOCAL" | awk '{print $1}')" "$EXPECTED_BASE_SHA"
bash -n "$LAUNCHER_LOCAL"

echo
echo "===== 3/9 GENERATE FOUR V23 PROFILE VARIANTS ====="
base64 -d > "$PKG/patch_v23.py" <<'PATCH_V23_B64'

PATCH_V23_B64
chmod +x "$PKG/patch_v23.py"
python3 -m py_compile "$PKG/patch_v23.py"

for spec in '0 0' '0 1' '1 0' '1 1'; do
    set -- $spec
    python3 "$PKG/patch_v23.py" "$BASE_LOCAL" "$PKG/visgrid-v23-t$1-p$2.lua" "$1" "$2"
done

base64 -d > "$PKG/patch_v23_diagbaseline.py" <<'PATCH_V23_DIAG_B64'

PATCH_V23_DIAG_B64
chmod +x "$PKG/patch_v23_diagbaseline.py"
python3 -m py_compile "$PKG/patch_v23_diagbaseline.py"
python3 "$PKG/patch_v23_diagbaseline.py" \
    "$PKG/visgrid-v23-t0-p0.lua" \
    "$PKG/visgrid-v23-diagnostic-baseline.lua"

assert_eq "diagnostic baseline SHA" "$(sha256sum "$PKG/visgrid-v23-diagnostic-baseline.lua" | awk '{print $1}')" "$EXPECTED_DIAG_SHA"
assert_eq "t0p0 SHA" "$(sha256sum "$PKG/visgrid-v23-t0-p0.lua" | awk '{print $1}')" "$EXPECTED_T0P0_SHA"
assert_eq "t0p1 SHA" "$(sha256sum "$PKG/visgrid-v23-t0-p1.lua" | awk '{print $1}')" "$EXPECTED_T0P1_SHA"
assert_eq "t1p0 SHA" "$(sha256sum "$PKG/visgrid-v23-t1-p0.lua" | awk '{print $1}')" "$EXPECTED_T1P0_SHA"
assert_eq "t1p1 SHA" "$(sha256sum "$PKG/visgrid-v23-t1-p1.lua" | awk '{print $1}')" "$EXPECTED_T1P1_SHA"

grep -Fq 'rayperf=2' "$PKG/visgrid-v23-diagnostic-baseline.lua"
grep -Fq 'diagnostic current-behavior baseline loaded' "$PKG/visgrid-v23-diagnostic-baseline.lua"
grep -Fq 'TSP_VISGRID_LUA_V23_PERF_MATRIX' "$PKG/visgrid-v23-t0-p0.lua"
grep -Fq 'TSP_VISGRID_V23PERF' "$PKG/visgrid-v23-t0-p0.lua"
grep -Fq 'v23RayMode = 1' "$PKG/visgrid-v23-t0-p1.lua"
grep -Fq 'v23TopologyMode = 1' "$PKG/visgrid-v23-t1-p0.lua"
grep -Fq 'TSP_VISGRID_V23MACRO' "$PKG/visgrid-v23-t1-p1.lua"

echo "Generated exact profile SHAs:"
sha256sum "$PKG/visgrid-v23-diagnostic-baseline.lua" "$PKG"/visgrid-v23-t*.lua

echo
echo "===== 4/9 LUA SYNTAX VALIDATION ====="
PARSER=""
for p in texlua lua luajit; do
    if command -v "$p" >/dev/null 2>&1; then PARSER="$p"; break; fi
done
if [ -n "$PARSER" ]; then
    cat > "$PKG/parsecheck.lua" <<'PARSECHECK'
local f=arg[1]
local c,e=loadfile(f)
if not c then error(e) end
print('PARSE PASS '..f)
PARSECHECK
    for f in "$BASE_LOCAL" "$PKG/visgrid-v23-diagnostic-baseline.lua" "$PKG"/visgrid-v23-t*.lua; do "$PARSER" "$PKG/parsecheck.lua" "$f"; done
else
    echo "NOTE: no host Lua parser found; exact SHA gates match independently parse-validated references."
fi

echo
echo "===== 5/9 PATCH + VALIDATE LIVE LAUNCHER COPY ====="
base64 -d > "$PKG/patch_launcher_v23.py" <<'PATCH_LAUNCH_B64'

PATCH_LAUNCH_B64
chmod +x "$PKG/patch_launcher_v23.py"
python3 -m py_compile "$PKG/patch_launcher_v23.py"
LAUNCHER_PATCHED="$PKG/Morrowind_51.v23.sh"
python3 "$PKG/patch_launcher_v23.py" "$LAUNCHER_LOCAL" "$LAUNCHER_PATCHED"
bash -n "$LAUNCHER_PATCHED"
grep -Fq '# >>> TSP_VISGRID_V23_PROFILE BEGIN' "$LAUNCHER_PATCHED"
grep -Fq 'VISGRID_PERFORMANCE=' "$LAUNCHER_PATCHED"
grep -Fq 'VISGRID_TOPOLOGY=' "$LAUNCHER_PATCHED"

BASELINE_VAL="$(awk -F= '/^VISGRID_BASELINE=[01]/{print $2; exit}' "$LAUNCHER_PATCHED" | awk '{print $1}')"
TOPOLOGY_VAL="$(awk -F= '/^VISGRID_TOPOLOGY=[01]/{print $2; exit}' "$LAUNCHER_PATCHED" | awk '{print $1}')"
PERFORMANCE_VAL="$(awk -F= '/^VISGRID_PERFORMANCE=[01]/{print $2; exit}' "$LAUNCHER_PATCHED" | awk '{print $1}')"
[ -n "$BASELINE_VAL" ] && [ -n "$TOPOLOGY_VAL" ] && [ -n "$PERFORMANCE_VAL" ] || fail "could not read patched launcher profile values"

echo "Initial launcher selection: baseline=$BASELINE_VAL topology=$TOPOLOGY_VAL performance=$PERFORMANCE_VAL"

echo
echo "===== 6/9 DEVICE BACKUP + TRANSACTIONAL INSTALL ====="
ssh "${SSH[@]}" "$DEV" "
    set -e
    mkdir -p '$BACKUP'
    cp -p '$LIVE_LUA' '$BACKUP/visgrid.lua.before'
    cp -p '$LAUNCHER' '$BACKUP/launcher.before'
    test -s '$BACKUP/visgrid.lua.before'
    test -s '$BACKUP/launcher.before'
"
BACKUP_READY=1

echo "Device backup: $BACKUP"

REMOTE_STAGE="$MOD/.v23-stage-$STAMP"
ssh "${SSH[@]}" "$DEV" "rm -rf '$REMOTE_STAGE'; mkdir -p '$REMOTE_STAGE'"
scp -q "${SSH[@]}" \
    "$BASE_LOCAL" \
    "$PKG/visgrid-v23-diagnostic-baseline.lua" \
    "$PKG/visgrid-v23-t0-p0.lua" \
    "$PKG/visgrid-v23-t0-p1.lua" \
    "$PKG/visgrid-v23-t1-p0.lua" \
    "$PKG/visgrid-v23-t1-p1.lua" \
    "$DEV:$REMOTE_STAGE/"
scp -q "${SSH[@]}" "$LAUNCHER_PATCHED" "$DEV:$REMOTE_STAGE/Morrowind_51.sh"

ssh "${SSH[@]}" "$DEV" "
    set -e
    test \"\$(sha256sum '$REMOTE_STAGE/visgrid-v22.1g-baseline.lua' | awk '{print \$1}')\" = '$EXPECTED_BASE_SHA'
    test \"\$(sha256sum '$REMOTE_STAGE/visgrid-v23-diagnostic-baseline.lua' | awk '{print \$1}')\" = '$EXPECTED_DIAG_SHA'
    test \"\$(sha256sum '$REMOTE_STAGE/visgrid-v23-t0-p0.lua' | awk '{print \$1}')\" = '$EXPECTED_T0P0_SHA'
    test \"\$(sha256sum '$REMOTE_STAGE/visgrid-v23-t0-p1.lua' | awk '{print \$1}')\" = '$EXPECTED_T0P1_SHA'
    test \"\$(sha256sum '$REMOTE_STAGE/visgrid-v23-t1-p0.lua' | awk '{print \$1}')\" = '$EXPECTED_T1P0_SHA'
    test \"\$(sha256sum '$REMOTE_STAGE/visgrid-v23-t1-p1.lua' | awk '{print \$1}')\" = '$EXPECTED_T1P1_SHA'
    bash -n '$REMOTE_STAGE/Morrowind_51.sh'

    rm -rf '$PROFILE_DIR.new'
    mkdir -p '$PROFILE_DIR.new'
    cp -p '$REMOTE_STAGE/visgrid-v22.1g-baseline.lua' '$PROFILE_DIR.new/'
    cp -p '$REMOTE_STAGE/visgrid-v23-diagnostic-baseline.lua' '$PROFILE_DIR.new/'
    cp -p '$REMOTE_STAGE/visgrid-v23-t0-p0.lua' '$PROFILE_DIR.new/'
    cp -p '$REMOTE_STAGE/visgrid-v23-t0-p1.lua' '$PROFILE_DIR.new/'
    cp -p '$REMOTE_STAGE/visgrid-v23-t1-p0.lua' '$PROFILE_DIR.new/'
    cp -p '$REMOTE_STAGE/visgrid-v23-t1-p1.lua' '$PROFILE_DIR.new/'
    rm -rf '$PROFILE_DIR.old'
    if [ -d '$PROFILE_DIR' ]; then mv '$PROFILE_DIR' '$PROFILE_DIR.old'; fi
    mv '$PROFILE_DIR.new' '$PROFILE_DIR'

    cp -p '$REMOTE_STAGE/Morrowind_51.sh' '$LAUNCHER.v23-new'
    chmod +x '$LAUNCHER.v23-new'
    mv -f '$LAUNCHER.v23-new' '$LAUNCHER'

    if [ '$BASELINE_VAL' = 1 ]; then
        SELECTED='$PROFILE_DIR/visgrid-v23-diagnostic-baseline.lua'
    else
        SELECTED='$PROFILE_DIR/visgrid-v23-t${TOPOLOGY_VAL}-p${PERFORMANCE_VAL}.lua'
    fi
    cp -p \"\$SELECTED\" '$LIVE_LUA.v23-new'
    mv -f '$LIVE_LUA.v23-new' '$LIVE_LUA'
    rm -rf '$REMOTE_STAGE'
    sync
"

echo
echo "===== 7/9 VERIFY INSTALLED MATRIX + PROTECTED STATE ====="
LIVE_SHA_AFTER="$(remote_sha "$LIVE_LUA")"
GAME_SHA_AFTER="$(remote_sha "$GAME")"
TOPO_SHA_AFTER="$(remote_sha "$TOPOLOGY")"
DOOR_SHA_AFTER="$(remote_sha "$DOORGRAPH")"
DB_STAT_AFTER="$(ssh "${SSH[@]}" "$DEV" "stat -c '%s %Y' '$DB'" | awk 'NF>=2 {print $1, $2; exit}' | tr -d '\r')"
TOPO_COUNT_AFTER="$(ssh "${SSH[@]}" "$DEV" "find '$TOPOLOGY_CELLS' -maxdepth 1 -type f -name 'c_*.lua' | wc -l" | awk 'NF {print $1; exit}' | tr -d '\r')"
DOOR_COUNT_AFTER="$(ssh "${SSH[@]}" "$DEV" "find '$DOORGRAPH_CELLS' -maxdepth 1 -type f -name 'c_*.lua' | wc -l" | awk 'NF {print $1; exit}' | tr -d '\r')"
LAUNCHER_SHA_AFTER="$(remote_sha "$LAUNCHER")"

assert_eq "game unchanged" "$GAME_SHA_AFTER" "$GAME_SHA_BEFORE"
assert_eq "topology loader unchanged" "$TOPO_SHA_AFTER" "$TOPO_SHA_BEFORE"
assert_eq "doorgraph loader unchanged" "$DOOR_SHA_AFTER" "$DOOR_SHA_BEFORE"
assert_eq "navmesh DB unchanged" "$DB_STAT_AFTER" "$DB_STAT_BEFORE"
assert_eq "topology shard count unchanged" "$TOPO_COUNT_AFTER" "$TOPO_COUNT_BEFORE"
assert_eq "doorgraph shard count unchanged" "$DOOR_COUNT_AFTER" "$DOOR_COUNT_BEFORE"

if [ "$BASELINE_VAL" = 1 ]; then EXPECTED_LIVE="$EXPECTED_DIAG_SHA"
elif [ "$TOPOLOGY_VAL:$PERFORMANCE_VAL" = '0:0' ]; then EXPECTED_LIVE="$EXPECTED_T0P0_SHA"
elif [ "$TOPOLOGY_VAL:$PERFORMANCE_VAL" = '0:1' ]; then EXPECTED_LIVE="$EXPECTED_T0P1_SHA"
elif [ "$TOPOLOGY_VAL:$PERFORMANCE_VAL" = '1:0' ]; then EXPECTED_LIVE="$EXPECTED_T1P0_SHA"
else EXPECTED_LIVE="$EXPECTED_T1P1_SHA"; fi
assert_eq "selected live sensor" "$LIVE_SHA_AFTER" "$EXPECTED_LIVE"

ssh "${SSH[@]}" "$DEV" "
    set -e
    bash -n '$LAUNCHER'
    grep -Fq '# >>> TSP_VISGRID_V23_PROFILE BEGIN' '$LAUNCHER'
    test \"\$(sha256sum '$PROFILE_DIR/visgrid-v22.1g-baseline.lua' | awk '{print \$1}')\" = '$EXPECTED_BASE_SHA'
    test \"\$(sha256sum '$PROFILE_DIR/visgrid-v23-diagnostic-baseline.lua' | awk '{print \$1}')\" = '$EXPECTED_DIAG_SHA'
    test \"\$(sha256sum '$PROFILE_DIR/visgrid-v23-t0-p0.lua' | awk '{print \$1}')\" = '$EXPECTED_T0P0_SHA'
    test \"\$(sha256sum '$PROFILE_DIR/visgrid-v23-t0-p1.lua' | awk '{print \$1}')\" = '$EXPECTED_T0P1_SHA'
    test \"\$(sha256sum '$PROFILE_DIR/visgrid-v23-t1-p0.lua' | awk '{print \$1}')\" = '$EXPECTED_T1P0_SHA'
    test \"\$(sha256sum '$PROFILE_DIR/visgrid-v23-t1-p1.lua' | awk '{print \$1}')\" = '$EXPECTED_T1P1_SHA'
"

echo "Installed live sensor SHA: $LIVE_SHA_AFTER"
echo "Installed launcher SHA:    $LAUNCHER_SHA_AFTER"

echo
echo "===== 8/9 WRITE PROFILE SWITCH + TRACE COLLECTOR ====="
SWITCH="$HOME/Downloads/set-visgrid-v23-profile.sh"
COLLECT="$HOME/Downloads/pull-visgrid-v23-perf-matrix.sh"
ROLLBACK="$HOME/Downloads/rollback-visgrid-v23-perf-matrix.sh"

cat > "$SWITCH" <<EOF_SWITCH
#!/usr/bin/env bash
set -Eeuo pipefail
DEV="\${TSP_DEV:-$DEV}"
LAUNCHER='$LAUNCHER'
mode="\${1:-}"
case "\$mode" in
  baseline) b=1; t=0; p=0 ;;
  current0) b=0; t=0; p=0 ;;
  current1) b=0; t=0; p=1 ;;
  macro0)   b=0; t=1; p=0 ;;
  macro1)   b=0; t=1; p=1 ;;
  *) echo "Usage: \$0 baseline|current0|current1|macro0|macro1"; exit 2 ;;
esac
ssh -o BatchMode=yes -o ConnectTimeout=8 "\$DEV" "
  set -e
  test -s '\$LAUNCHER'
  grep -Fq '# >>> TSP_VISGRID_V23_PROFILE BEGIN' '\$LAUNCHER'
  sed -i 's/^VISGRID_BASELINE=[01].*/VISGRID_BASELINE=\$b/' '\$LAUNCHER'
  sed -i 's/^VISGRID_TOPOLOGY=[01].*/VISGRID_TOPOLOGY=\$t/' '\$LAUNCHER'
  sed -i 's/^VISGRID_PERFORMANCE=[01].*/VISGRID_PERFORMANCE=\$p/' '\$LAUNCHER'
  bash -n '\$LAUNCHER'
  grep -E '^VISGRID_(BASELINE|TOPOLOGY|PERFORMANCE)=' '\$LAUNCHER'
"
echo "Selected \$mode. It takes effect the next time Morrowind_51 is launched."
EOF_SWITCH
chmod +x "$SWITCH"
bash -n "$SWITCH"

cat > "$COLLECT" <<EOF_COLLECT
#!/usr/bin/env bash
set -Eeuo pipefail
cd "\$HOME/Downloads"
DEV="\${TSP_DEV:-$DEV}"
ROOT='$ROOT'
LUA='$LIVE_LUA'
LAUNCHER='$LAUNCHER'
STAMP="\$(date +%Y%m%d-%H%M%S)"
OUT="\$HOME/Downloads/visgrid-v23-perf-matrix-\$STAMP.txt"
RINGOUT="\$HOME/Downloads/tsp_ring-v23-\$STAMP.txt"
{
  echo '===== ACTIVE V23 PROFILE ====='
  ssh -o BatchMode=yes -o ConnectTimeout=8 "\$DEV" "
    sha256sum '\$LUA'
    grep -n -E 'TSP_VISGRID_LUA_V23_PERF_MATRIX|TSP_VISGRID_LUA_V22_1G_STRUCTURAL_PVS_SAFETY' '\$LUA' | head -8 || true
    echo
    echo 'Launcher selection:'
    grep -E '^VISGRID_(BASELINE|TOPOLOGY|PERFORMANCE)=' '\$LAUNCHER' || true
  "
  echo
  echo '===== COMPACT V23 PERF / MACRO TRACE ====='
  ssh -o BatchMode=yes -o ConnectTimeout=8 "\$DEV" "
    for f in '\$ROOT/openmw_051_log.txt' '\$ROOT/config-0.51/openmw.log'; do
      [ -s \"\$f\" ] || continue
      echo \"--- \$f ---\"
      tail -n 30000 \"\$f\" | grep -E 'TSP_VISGRID_V23PERF|TSP_VISGRID_V23MACRO|TSP_VISGRID_V23\\]|sensor DISABLED| ERROR #' | tail -n 1400 || true
    done
  "
  echo
  echo '===== RECENT LEGACY SENSOR STATUS ====='
  ssh -o BatchMode=yes -o ConnectTimeout=8 "\$DEV" "
    for f in '\$ROOT/openmw_051_log.txt' '\$ROOT/config-0.51/openmw.log'; do
      [ -s \"\$f\" ] || continue
      echo \"--- \$f ---\"
      tail -n 30000 \"\$f\" | grep -E 'TSP_VISGRID_V11\\].*budget=|Changing to interior|Loading cell ' | tail -n 300 || true
    done
  "
} | tee "\$OUT"
if scp -q -o BatchMode=yes -o ConnectTimeout=8 "\$DEV:/mnt/SDCARD/tsp_ring.txt" "\$RINGOUT" 2>/dev/null; then
  echo "Ring capture: \$RINGOUT"
else
  echo 'No /mnt/SDCARD/tsp_ring.txt copied.'
fi
echo "Trace: \$OUT"
EOF_COLLECT
chmod +x "$COLLECT"
bash -n "$COLLECT"

cat > "$ROLLBACK" <<EOF_ROLLBACK
#!/usr/bin/env bash
set -Eeuo pipefail
DEV="\${TSP_DEV:-$DEV}"
ROOT='$ROOT'
MOD='${MOD}'
LUA='${LIVE_LUA}'
LAUNCHER='$LAUNCHER'
BACKUP='$BACKUP'
ssh -o BatchMode=yes -o ConnectTimeout=8 "\$DEV" "
  set -e
  test -s '\$BACKUP/visgrid.lua.before'
  test -s '\$BACKUP/launcher.before'
  cp -p '\$BACKUP/visgrid.lua.before' '\$LUA.rollback-new'
  mv -f '\$LUA.rollback-new' '\$LUA'
  cp -p '\$BACKUP/launcher.before' '\$LAUNCHER.rollback-new'
  chmod +x '\$LAUNCHER.rollback-new'
  mv -f '\$LAUNCHER.rollback-new' '\$LAUNCHER'
  sync
  echo 'Restored:'
  sha256sum '\$LUA' '\$LAUNCHER'
"
echo 'V23 live sensor + launcher rolled back. Staged v23_profiles are harmless and were left in place.'
EOF_ROLLBACK
chmod +x "$ROLLBACK"
bash -n "$ROLLBACK"

echo "Switch helper: $SWITCH"
echo "Collector:     $COLLECT"
echo "Rollback:      $ROLLBACK"

echo
echo "===== 9/9 FINAL PASS ====="
trap - ERR
BACKUP_READY=0

echo "PASS: OpenMW binary unchanged:     $GAME_SHA_AFTER"
echo "PASS: topology loader unchanged:   $TOPO_SHA_AFTER"
echo "PASS: doorgraph loader unchanged:  $DOOR_SHA_AFTER"
echo "PASS: navmesh.db unchanged:        $DB_STAT_AFTER"
echo "PASS: exact V22.1G source baseline + diagnostic current-behavior profile staged."
echo "PASS: four exact V23 matrix variants staged and launcher-selectable."
echo "PASS: tsp_state diagnostics were NOT changed by this patch."
echo
echo "Initial selection:"
echo "  Visgrid Baseline=$BASELINE_VAL"
echo "  Visgrid Topology=$TOPOLOGY_VAL"
echo "  Visgrid Performance=$PERFORMANCE_VAL"
echo
echo "Recommended first run is baseline (current V22.1G behavior + timing probe)."
echo "After one Manor District run:"
echo "  cd ~/Downloads && ./pull-visgrid-v23-perf-matrix.sh"
echo
echo "Installer log: $LOG"
echo "Package:       $PKG"
